        self._validate_coordinates(x1, y1, x2, y2)
        for y in range(y1, y2 + 1):
            for x in range(x1, x2 + 1):
                self.grid[y][x] = True

    def turn_off(self, x1: int, y1: int, x2: int, y2: int) -> None:
        self._validate_coordinates(x1, y1, x2, y2)
        for y in range(y1, y2 + 1):
            for x in range(x1, x2 + 1):
                self.grid[y][x] = False

    def toggle(self, x1: int, y1: int, x2: int, y2: int) -> None:
        self._validate_coordinates(x1, y1, x2, y2)
        for y in range(y1, y2 + 1):
            for x in range(x1, x2 + 1):
