class RoomPlanner:
    def __init__(self):
        self._rooms = {}
        self._bookings = {}

    def add_room(self, room: str) -> None:
        if not room:
            raise ValueError("Room name cannot be empty")
        if room in self._rooms:
            raise BookingError(f"Room '{room}' already exists")
        self._rooms[room] = []

    def book(self, booking_id: str, room: str, slot: int) -> None:
        if room not in self._rooms:
            raise KeyError(f"Room '{room}' does not exist")
        if not booking_id or booking_id is None:
            raise ValueError("Booking ID cannot be empty or None")
        if slot < 0:
            raise ValueError("Slot number cannot be below 0")
        if booking_id in self._bookings:
            raise BookingError(f"Booking ID '{booking_id}' is already used")
        if slot in self._rooms[room]:
            raise RoomBusy(f"Room '{room}' is already booked in slot {slot}")

        self._rooms[room].append(slot)
        self._bookings[booking_id] = (room, slot)

    def get_booking(self, booking_id: str) -> tuple[str, int]:
        if booking_id not in self._bookings:
            raise KeyError(f"Booking ID '{booking_id}' does not exist")
        return self._bookings[booking_id]

    def get_bookings(self) -> list[str]:
        return list(self._bookings.keys())

    def get_free_rooms(self, slot: int) -> list[str]:
        if slot < 0:
            raise ValueError("Slot number cannot be below 0")
        free_rooms = []
        for room, slots in self._rooms.items():
            if slot not in slots:
                free_rooms.append(room)
        return free_rooms

    def get_rooms(self) -> list[str]:
        return list(self._rooms.keys())
