class SeatPlanner:
    def __init__(self):
        self.coaches = {}
        self.bookings = {}

    def add_coach(self, coach_id: str, seats: int) -> None:
        if not coach_id:
            raise ValueError("Empty coach ID")
        if seats <= 0:
            raise ValueError("Non-positive number of seats")
        if coach_id in self.coaches:
            raise ReservationError("Coach ID already exists")
        self.coaches[coach_id] = seats * 7 // 10

    def reserve(self, booking_id: str, size: int) -> str:
        if not booking_id:
            raise ValueError("Empty booking ID")
        if size <= 0:
            raise ValueError("Non-positive group size")
        if booking_id in self.bookings:
            raise ReservationError("Booking ID already exists")
        for coach_id, limit in self.coaches.items():
            if self.get_reserved(coach_id) + size <= limit:
                self.bookings[booking_id] = (coach_id, size)
                return coach_id
        raise NotEnoughSeats("Not enough seats for the group")

    def move(self, booking_id: str, coach_id: str) -> None:
        if booking_id not in self.bookings:
            raise KeyError("Unknown booking ID")
        if coach_id not in self.coaches:
            raise KeyError("Unknown coach ID")
        old_coach_id, size = self.bookings[booking_id]
        if old_coach_id == coach_id:
            raise ValueError("Booking already in the target coach")
        if self.get_reserved(coach_id) + size > self.coaches[coach_id]:
            raise NotEnoughSeats("Not enough seats for the group in the target coach")
        self.bookings[booking_id] = (coach_id, size)

    def get_booking(self, booking_id: str) -> tuple[str, int]:
        if booking_id not in self.bookings:
            raise KeyError("Unknown booking ID")
        return self.bookings[booking_id]

    def get_reserved(self, coach_id: str) -> int:
        if coach_id not in self.coaches:
            raise KeyError("Unknown coach ID")
        return sum(size for coach, size in self.bookings.values() if coach == coach_id)

    def get_available(self, coach_id: str) -> int:
        if coach_id not in self.coaches:
            raise KeyError("Unknown coach ID")
        return self.coaches[coach_id] - self.get_reserved(coach_id)

    def get_coaches(self) -> list[str]:
        return list(self.coaches.keys())
