        new_coach = self.coaches[coach_id]
        if new_coach["limit"] - new_coach["reserved"] < size:
            raise NotEnoughSeats("Not enough seats for the group")
        old_coach["reserved"] -= size
        new_coach["reserved"] += size
        self.bookings[booking_id] = (coach_id, size)

