        if customer not in self.subscriptions:
            raise KeyError("Customer not found")
        return self.subscriptions[customer]

    def get_charges(self, customer: str) -> list[int]:
        if customer not in self.charges:
            raise KeyError("Customer not found")
        return self.charges[customer]
